import json

log_path = "/home/USER/runs/paper/qwen-h0-card-u4/frozen/seen-reference-4/play/users/u023/system/state/sessions/01a1ac30-26e2-72ce-851e-6bd9c2f5f977.jsonl"

with open(log_path) as f:
    all_lines = f.readlines()

# Search for any grid data in tool results
print("Searching for grid data in all tool results...")
for i, line in enumerate(all_lines):
    entry = json.loads(line)
    if entry.get('role') == 'toolResult':
        content = entry.get('content', [])
        text_parts = []
        for item in content:
            if isinstance(item, dict) and item.get('type') == 'text':
                text_parts.append(item.get('text', ''))
        if text_parts:
            full_text = ''.join(text_parts)[:200]
            # Check if it looks like grid data (numbers separated by spaces)
            if any(c.isdigit() for c in full_text):
                print(f"\nEntry {i}:")
                print(json.dumps({k:v for k,v in entry.items() if k not in ['id','parentId']}, indent=2)[:600])
